insert into practice_exercises (id, subject_name, level, title, source) values
  ('3f704958-4409-4a7c-9c44-595b84c3ac6f', $$Biologie$$, $$VWO$$, $$Nicotine tijdens de vroege embryonale ontwikkeling$$, $$VWO Biologie 2024-I$$),
  ('5d945d86-2e52-4631-bcbd-330e5796136b', $$Biologie$$, $$VWO$$, $$Spitsbergenrendier verandert zijn dieet$$, $$VWO Biologie 2024-I$$),
  ('37f844eb-46da-4308-b3c9-a5d59e4a5dc0', $$Biologie$$, $$VWO$$, $$Koolmezen dood door bestrijding buxusmot?$$, $$VWO Biologie 2024-I$$),
  ('3b84ae88-2767-4f56-878d-dbe045a1a716', $$Biologie$$, $$VWO$$, $$Drop$$, $$VWO Biologie 2024-I$$),
