insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('c029df56-6e40-4b6b-8c9b-b413af5c00d5', '3f704958-4409-4a7c-9c44-595b84c3ac6f', $$inleiding: onderzoek naar het effect van nicotine op het embryo$$,
   $$biologie-vwo-2024-i-nicotine-tijdens-de-vroege-embryonale-ontwikkeling-context1.png$$,
   $$Het is al lang bekend dat roken tijdens de zwangerschap kan leiden tot een miskraam, een laag geboortegewicht, vroeggeboorte en nadelige gezondheidseffecten bij de baby. Amerikaanse wetenschappers van de Stanford University School of Medicine hebben een model ontwikkeld om te onderzoeken hoe nicotine een embryo beïnvloedt.$$, 'inline'),
  ('50a9e600-dfdb-4025-9746-c2468d5f4741', '3f704958-4409-4a7c-9c44-595b84c3ac6f', $$nicotine bindt aan acetylcholinereceptoren in het beloningscentrum (afbeelding 1)$$,
   $$biologie-vwo-2024-i-nicotine-tijdens-de-vroege-embryonale-ontwikkeling-context2.png$$,
   $$Nicotine is een gifstof met verslavende en verdovende effecten. In het beloningscentrum van de grote hersenen bindt nicotine aan acetylcholinereceptoren die zich bevinden op de axonen van dopamine- producerende neuronen. Zowel na binding van acetylcholine als na binding van nicotine, neemt de dopamine-afgifte in de synaps toe, waardoor het beloningscentrum actiever wordt. Dopamine wordt heropgenomen in het presynaptisch neuron (afbeelding 1).
afbeelding 1$$, 'inline'),
  ('408fa9c0-4352-480b-94be-207e3d0c13fb', '3f704958-4409-4a7c-9c44-595b84c3ac6f', $$drie uitspraken over afbeelding 1: antagonist, endocytose, heropname$$,
   $$biologie-vwo-2024-i-nicotine-tijdens-de-vroege-embryonale-ontwikkeling-context3.png$$,
   $$Over afbeelding 1 worden de volgende uitspraken gedaan:
1 Nicotine is een antagonist van acetylcholine.
2 Dopamine komt via endocytose in de synapsspleet terecht.
3 Heropname van dopamine vindt plaats door dopaminereceptoren.$$, 'inline'),
  ('cbeaa738-2044-4a96-a4cb-309d121c3278', '3f704958-4409-4a7c-9c44-595b84c3ac6f', $$nicotine wordt niet afgebroken door acetylcholinesterase$$,
   $$biologie-vwo-2024-i-nicotine-tijdens-de-vroege-embryonale-ontwikkeling-context4.png$$,
   $$Nicotine wordt niet afgebroken door acetylcholinesterase, dat in de weefselvloeistof aanwezig is.$$, 'inline'),
  ('10eb60cf-fc06-42b9-98dc-cdc192a3b389', '3f704958-4409-4a7c-9c44-595b84c3ac6f', $$nicotine wordt geproduceerd door planten van de familie Solanaceae$$,
   $$biologie-vwo-2024-i-nicotine-tijdens-de-vroege-embryonale-ontwikkeling-context5.png$$,
   $$De gifstof nicotine wordt gemaakt door planten van de familie Solanaceae. In deze familie worden de grootste hoeveelheden nicotine geproduceerd door de planten van het geslacht Nicotiana.$$, 'inline'),
  ('7fdebe83-805f-4321-9f5b-896a77c45e07', '3f704958-4409-4a7c-9c44-595b84c3ac6f', $$tabaksplanten hebben door kruisen en selecteren hogere nicotinegehaltes dan wilde planten$$,
   $$biologie-vwo-2024-i-nicotine-tijdens-de-vroege-embryonale-ontwikkeling-context6.png$$,
   $$Nicotiana-soorten die gebruikt worden voor de productie van tabak hebben hogere gehaltes aan nicotine dan wilde tabaksplanten. Dit komt door een bepaald proces waarbij door middel van kruisingen en selectie een hogere aanmaak van nicotine in deze productiesoorten is verkregen.$$, 'inline'),
  ('b2b12ded-8aa7-4af7-bcde-a30e82445f2a', '3f704958-4409-4a7c-9c44-595b84c3ac6f', $$onderzoeksopzet met embryoid bodies (EB''s) uit menselijke stamcellen (afbeelding 2)$$,
   $$biologie-vwo-2024-i-nicotine-tijdens-de-vroege-embryonale-ontwikkeling-context7.png$$,
   $$De Amerikaanse wetenschappers wilden onderzoeken hoe nicotine de verschillende celtypen in een embryo beïnvloedt. Onderzoek doen aan menselijke embryo’s is in veel landen niet toegestaan of mag alleen onder zeer strikte voorwaarden. Daarom gebruikten de wetenschappers stamcellen afkomstig uit een menselijk embryo van vijf dagen oud (blastula). Een kweek van deze stamcellen vormt spontaan bolletjes die ‘embryoid bodies’ (EB’s) worden genoemd. Om het effect van nicotine op de ontwikkeling van deze stamcellen te onderzoeken, voegden de wetenschappers nicotine toe aan het kweekmedium. De opzet van het onderzoek is in afbeelding 2 weergegeven.
afbeelding 2$$, 'inline'),
  ('471e0ebc-5fc0-442c-ad55-a6b99a630584', '3f704958-4409-4a7c-9c44-595b84c3ac6f', $$stamcellen hebben een bepaalde potentie$$,
   $$biologie-vwo-2024-i-nicotine-tijdens-de-vroege-embryonale-ontwikkeling-context8.png$$,
   $$Stamcellen hebben een bepaalde potentie.$$, 'inline'),
  ('005b168c-070a-4f40-98bb-22eea5c67f47', '3f704958-4409-4a7c-9c44-595b84c3ac6f', $$diameter van EB''s als maat voor celaantal, met en zonder nicotine (afbeelding 3, afbeelding 4)$$,
   $$biologie-vwo-2024-i-nicotine-tijdens-de-vroege-embryonale-ontwikkeling-context9.png$$,
   $$De concentratie nicotine van het kweekmedium was gelijk aan de gemiddelde concentratie in het bloed van embryo’s waarvan de moeder rookt. Na 21 dagen incubatie werd de diameter van de EB’s bepaald. De diameter is een maat voor het aantal cellen in de EB’s. Afbeelding 3 toont een microscopisch beeld van EB’s die aan nicotine zijn blootgesteld en van controle-EB’s. De EB’s zijn als donkere vlekken zichtbaar. In afbeelding 4 zijn de metingen van de diameter van de EB’s in de twee groepen weergegeven.
afbeelding 3 afbeelding 4
* significant verschil in gemiddelde diameter$$, 'inline'),
  ('d95b9552-8168-4c25-81d1-46d6e71f6b43', '3f704958-4409-4a7c-9c44-595b84c3ac6f', $$twee uitspraken over het diameterverschil tussen controle- en nicotine-EB''s$$,
   $$biologie-vwo-2024-i-nicotine-tijdens-de-vroege-embryonale-ontwikkeling-context10.png$$,
   $$Over het resultaat worden de volgende uitspraken gedaan:
1 Het aantal cellen in een controle-EB is gemiddeld groter dan in een EB die aan nicotine is blootgesteld.
2 Het verschil in gemiddelde diameter tussen de twee groepen EB’s berust op toeval.$$, 'inline'),
  ('6cc72f79-1ae8-4889-8658-b59979c0bac6', '3f704958-4409-4a7c-9c44-595b84c3ac6f', $$onderzoek naar het effect van nicotine op genexpressie per celtype$$,
   $$biologie-vwo-2024-i-nicotine-tijdens-de-vroege-embryonale-ontwikkeling-context11.png$$,
   $$De onderzoekers hebben ook het effect van nicotine op de genexpressie van de EB’s onderzocht. Om de verschillen in expressie tussen verschillende celtypen te onderzoeken, werd de genexpressie van afzonderlijke cellen bepaald.$$, 'inline'),
  ('8d2eccc3-a35e-4314-be77-e1808f24b722', '3f704958-4409-4a7c-9c44-595b84c3ac6f', $$bepalen van genexpressie via cDNA en PCR; indeling in celtypen (afbeelding 5)$$,
   $$biologie-vwo-2024-i-nicotine-tijdens-de-vroege-embryonale-ontwikkeling-context12.png$$,
   $$Om de genexpressie te bepalen werd – op basis van al het RNA – cDNA gemaakt, dat vervolgens werd vermenigvuldigd met de PCR-techniek. Aan de hand van de gevonden genexpressie werd een expressieprofiel opgesteld waarmee de cellen konden worden ingedeeld in verschillende celtypen. Afbeelding 5 toont de stappen van dit deel van het onderzoek.
afbeelding 5$$, 'inline'),
  ('1c36f369-8148-49df-8563-0a04de37088d', '3f704958-4409-4a7c-9c44-595b84c3ac6f', $$drie uitspraken over de stappen in afbeelding 5: cDNA versus PCR$$,
   $$biologie-vwo-2024-i-nicotine-tijdens-de-vroege-embryonale-ontwikkeling-context13.png$$,
   $$Over de stappen in afbeelding 5 worden de volgende uitspraken gedaan:
1 Om cDNA te maken, zijn andere enzymen nodig dan bij de PCR.
2 Om cDNA te maken, zijn andere nucleotiden nodig dan bij de PCR.
3 Bij de PCR in dit onderzoek wordt in totaal één kenmerkend gen vermenigvuldigd.$$, 'inline'),
  ('25170068-3d04-4133-94c3-1c5a88c19101', '3f704958-4409-4a7c-9c44-595b84c3ac6f', $$tabel: celtypen met veranderde genexpressie door nicotine en het effect daarvan$$,
   $$biologie-vwo-2024-i-nicotine-tijdens-de-vroege-embryonale-ontwikkeling-context14.png$$,
   $$In de tabel hieronder zijn twee celtypen genoemd waarvan de genexpressie was veranderd door nicotine, met het bijbehorend effect op de embryonale ontwikkeling.
celtype effect van nicotine
1 epitheelcellen toename van celdeling
2 endotheelcellen verminderde vorming van haarvaten$$, 'inline'),
  ('1ea72386-9e1f-4872-bf56-35a91293ea0a', '3f704958-4409-4a7c-9c44-595b84c3ac6f', $$kinderen van rokende moeders hebben later meer kans op longproblemen$$,
   $$biologie-vwo-2024-i-nicotine-tijdens-de-vroege-embryonale-ontwikkeling-context15.png$$,
   $$Kinderen van wie de moeder rookte tijdens de zwangerschap, hebben op latere leeftijd een grotere kans op longproblemen.$$, 'inline'),
  ('a560d33e-9c6d-4924-9e44-28e648bfb16b', '3f704958-4409-4a7c-9c44-595b84c3ac6f', $$tekortkoming van EB''s als model voor onderzoek naar effecten tijdens de zwangerschap$$,
   $$biologie-vwo-2024-i-nicotine-tijdens-de-vroege-embryonale-ontwikkeling-context16.png$$,
   $$Het is niet ideaal om EB’s te gebruiken als een model om de gevolgen van nicotinegebruik tijdens de zwangerschap op de ontwikkeling van het embryo te onderzoeken. Een voorbeeld van een tekortkoming is dat een EB geen echt embryo is en effecten voor de latere periode van de zwangerschap dus niet bestudeerd kunnen worden.$$, 'inline'),
  ('5a6933d9-97af-48a2-a265-bb8b261e3dbb', '5d945d86-2e52-4631-bcbd-330e5796136b', $$inleiding: ijslagen door klimaatverandering veranderen het dieet van het Spitsbergenrendier$$,
   $$biologie-vwo-2024-i-spitsbergenrendier-verandert-zijn-dieet-context1.png$$,
   $$Door klimaatverandering wordt de vegetatie in arctische gebieden ’s winters steeds vaker door een ijslaag bedekt. De Noorse bioloog Brage Bremset Hansen en zijn collega’s hebben aangetoond dat het dieet van Spitsbergenrendieren dan verandert. Dit veroorzaakt een verandering in de nutriëntenkringloop in het ecosysteem.$$, 'inline'),
  ('1135ee6b-424d-4a1d-8434-64c72eeb3e3c', '5d945d86-2e52-4631-bcbd-330e5796136b', $$het Spitsbergenrendier als kleinste ondersoort, met korte poten en dikke vacht (afbeelding 1, afbeelding 2)$$,
   $$biologie-vwo-2024-i-spitsbergenrendier-verandert-zijn-dieet-context2.png$$,
   $$Rendieren komen voor op de toendra’s in het gebied rondom de Noordpool. Het Spitsbergenrendier (Rangifer tarandus platyrhynchus) is de kleinste van de zeven ondersoorten en komt alleen voor op Spitsbergen, een eilandengroep in de Noordelijke IJszee (afbeelding 1). Het Spitsbergenrendier heeft korte poten, een relatief kleine, ronde kop en een dikke vacht (afbeelding 2).
afbeelding 1 afbeelding 2$$, 'inline'),
  ('4422ee03-bada-463d-8e77-5b7274b3bed1', '5d945d86-2e52-4631-bcbd-330e5796136b', $$voedsel en vetopslag van het Spitsbergenrendier$$,
   $$biologie-vwo-2024-i-spitsbergenrendier-verandert-zijn-dieet-context3.png$$,
   $$Spitsbergenrendieren eten grassen, mossen en dwergstruikjes. In de zomerperiode slaan ze overtollige energie uit het voedsel op in een dikke vetlaag. Om in de winter bij hun voedsel te komen, schrapen ze sneeuw weg met hun hoeven.$$, 'inline'),
  ('da55624b-cc79-4ca8-bff0-39c176a7b542', '5d945d86-2e52-4631-bcbd-330e5796136b', $$aanpassingen aan de kou: dikke vacht en gunstige oppervlakte-inhoudsverhouding$$,
   $$biologie-vwo-2024-i-spitsbergenrendier-verandert-zijn-dieet-context4.png$$,
   $$Een aantal aanpassingen maakten deze ondersoort geschikt om te overleven in de kou op Spitsbergen. Zo hebben ze een dikke vacht, waardoor ze minder energie verbruiken om warm te blijven, en door hun korte poten is hun oppervlakte-inhoudsverhouding gunstig.$$, 'inline'),
  ('dfdbceee-45c0-42f9-8947-ae731d80696f', '5d945d86-2e52-4631-bcbd-330e5796136b', $$kleinere lichaamsgrootte dan andere ondersoorten, mogelijk door afwezigheid van predatoren$$,
   $$biologie-vwo-2024-i-spitsbergenrendier-verandert-zijn-dieet-context5.png$$,
   $$De poten van het Spitsbergenrendier zijn kort, maar ook de rest van zijn lichaam is klein vergeleken met ondersoorten die op andere plaatsen leven. Een mogelijke verklaring hiervoor is de afwezigheid van predatoren zoals de wolf. Kleinere dieren vallen daardoor niet vaker ten prooi aan wolven dan grotere exemplaren. Selectiedruk door andere factoren leidde tot de kleine ondersoort op Spitsbergen.$$, 'inline'),
  ('e87a16fd-c35f-4a84-b7eb-0d55cd1fc82c', '5d945d86-2e52-4631-bcbd-330e5796136b', $$temperatuurstijging verhoogt de productiviteit van de vegetatie; drie effecten$$,
   $$biologie-vwo-2024-i-spitsbergenrendier-verandert-zijn-dieet-context6.png$$,
   $$Onderzoekers hebben geconstateerd dat temperatuurstijging als gevolg van klimaatverandering in de arctische gebieden een hogere productiviteit van de vegetatie veroorzaakt. Een aantal effecten van temperatuurstijging zijn:
1 De dissimilatie door plantencellen neemt toe.
2 De periode waarin reducenten in de bodem actief zijn, wordt langer.
3 De stikstofassimilatie verloopt sneller.$$, 'inline'),
  ('aafb6249-88af-4242-88a9-709ae8945c5f', '5d945d86-2e52-4631-bcbd-330e5796136b', $$toenemende populatiegrootte van sommige herbivoren door hogere productiviteit$$,
   $$biologie-vwo-2024-i-spitsbergenrendier-verandert-zijn-dieet-context7.png$$,
   $$De populatiegrootte van sommige soorten herbivoren neemt toe door een hogere productiviteit van de vegetatie.$$, 'inline'),
  ('d2c98076-7b04-4ce4-84dc-4e12be37a0f7', '5d945d86-2e52-4631-bcbd-330e5796136b', $$ijslagen door regen-op-sneeuw belemmeren voedselopname; hypothese over zeewier eten$$,
   $$biologie-vwo-2024-i-spitsbergenrendier-verandert-zijn-dieet-context8.png$$,
   $$In de winter is de vegetatie op Spitsbergen bedekt met sneeuw. Wanneer er regen valt op het sneeuwdek, vormt zich een ijslaag over de vegetatie. Hierdoor kunnen herbivoren minder makkelijk aan voedsel komen. Deze ijslagen komen door klimaatverandering vaker voor. Hansen en collega’s onderzochten wat het effect hiervan is op het dieet van Spitsbergenrendieren. Hun hypothese was dat als landplanten onbereikbaar zijn, Spitsbergenrendieren zeewier eten dat is aangespoeld op de kust.$$, 'inline'),
  ('097f9bdb-6b6b-4cc5-bfb4-53e2061c4358', '5d945d86-2e52-4631-bcbd-330e5796136b', $$negenjarig onderzoek naar ijslaagdikte en voedsel zoeken aan de kust (afbeelding 3)$$,
   $$biologie-vwo-2024-i-spitsbergenrendier-verandert-zijn-dieet-context9.png$$,
   $$De onderzoekers bepaalden negen jaar lang de ruimtelijke spreiding van Spitsbergenrendieren en de gemiddelde dikte van de ijslaag die ontstaat door regen-op-sneeuw. In afbeelding 3 is de relatie weergegeven tussen de dikte van de ijslaag en het aandeel Spitsbergenrendieren dat aan de kust voedsel zoekt. Elk bolletje stelt het gemiddelde voor van één jaar van een bepaalde populatie.
afbeelding 3$$, 'inline'),
  ('8d3d8f77-c1de-4dfb-9bcf-422c4217b0ef', '5d945d86-2e52-4631-bcbd-330e5796136b', $$drie uitspraken over afbeelding 3$$,
   $$biologie-vwo-2024-i-spitsbergenrendier-verandert-zijn-dieet-context10b.png$$,
   $$Over afbeelding 3 worden de volgende uitspraken gedaan:
1 Alleen wanneer er een ijslaag aanwezig is, zoeken Spitsbergenrendieren voedsel aan de kust.
2 Het aandeel Spitsbergenrendieren dat aan de kust voedsel zoekt in populatie 1 wordt gemiddeld groter naarmate de ijslaag dikker is.
3 Als de ijsdikte meer dan 9 cm is, zoekt 31% van de Spitsbergenrendieren uit populatie 2 voedsel aan de kust.$$, 'inline'),
  ('e4306ef0-d91e-4c93-bb9b-bcaf2c58bec1', '5d945d86-2e52-4631-bcbd-330e5796136b', $$dieetverandering bevestigd via uitwerpselenonderzoek; effect op de stikstofkringloop$$,
   $$biologie-vwo-2024-i-spitsbergenrendier-verandert-zijn-dieet-context11.png$$,
   $$Met een onderzoek aan de uitwerpselen toonden de onderzoekers aan dat het dieet van Spitsbergenrendieren inderdaad is veranderd: Spitsbergenrendieren blijken nu ook zeewier te eten. Het veranderde dieet heeft invloed op de lokale stikstofkringloop.$$, 'inline'),
  ('e0dc24f0-aeee-4187-be44-0c5078bb09c0', '37f844eb-46da-4308-b3c9-a5d59e4a5dc0', $$inleiding: veel dode koolmeesjongen gevonden in het voorjaar van 2018$$,
   $$biologie-vwo-2024-i-koolmezen-dood-door-bestrijding-buxusmot-context1.png$$,
   $$In het voorjaar van 2018 kwamen er verontrustende berichten over opvallend veel dode koolmeesjongen in nestkasten. Ook Henriëtte had zo’n nestje met dode koolmezen in de tuin.$$, 'inline'),
  ('7ddec32d-d9c8-4ae5-a319-6b4ef24a1e79', '37f844eb-46da-4308-b3c9-a5d59e4a5dc0', $$de koolmees als broedvogel; Henriëtte bestrijdt de buxusmot in haar tuin$$,
   $$biologie-vwo-2024-i-koolmezen-dood-door-bestrijding-buxusmot-context2.png$$,
   $$De koolmees (Parus major, afbeelding 1) is een veelvoorkomende broedvogel in Nederland. De koolmees leeft van zaden en insecten. Totdat jonge koolmezen het nest verlaten, worden ze door hun ouders gevoerd met kleine insecten zoals de rupsen van de buxusmot.
afbeelding 1 In 2018 en 2019 hadden veel Nederlandse tuineigenaren last van de rupsen van de buxusmot. Ook Henriëttes buxus-heg werd kaalgevreten. In het tuincentrum haalde ze toen een middel om de buxusmot te bestrijden. Henriëtte vraagt zich nu af of het nestje dode koolmeesjes in haar tuin misschien het gevolg was van dit bestrijdingsmiddel.$$, 'inline'),
  ('1ff7d391-88fe-47ff-988f-907734d0864c', '37f844eb-46da-4308-b3c9-a5d59e4a5dc0', $$pyrethroïden blokkeren spanningsafhankelijke Na⁺-kanalen; drie uitspraken over het effect op een neuron$$,
   $$biologie-vwo-2024-i-koolmezen-dood-door-bestrijding-buxusmot-context3.png$$,
   $$Veel insectenbestrijdingsmiddelen behoren tot de pyrethroïden. Deze stoffen verhinderen het sluiten van de spannings-afhankelijke Na⁺-kanalen in de uitlopers van neuronen. Over het effect van pyrethroïden op een neuron worden de volgende uitspraken gedaan:
1 Door pyrethroïden ontstaan er constant nieuwe impulsen in de axonen.
2 Doordat de Na⁺-kanalen niet sluiten, treedt hyperpolarisatie op.
3 De oorspronkelijke rustpotentiaal wordt niet meer bereikt.$$, 'inline'),
  ('914667c8-eacf-4564-b637-a3b86b3b9150', '37f844eb-46da-4308-b3c9-a5d59e4a5dc0', $$onderzoek naar bestrijdingsmiddelen in 41 nesten met dode koolmezen (tabel 1)$$,
   $$biologie-vwo-2024-i-koolmezen-dood-door-bestrijding-buxusmot-context4.png$$,
   $$In het voorjaar van 2019 hebben onderzoekers van het Centrum voor Landbouw en Milieu 41 nesten met dode jonge koolmezen onderzocht op aanwezigheid van diverse bestrijdingsmiddelen in de koolmezen. Er waren nesten uit stedelijke gebieden waar bestrijdingsmiddelen tegen de buxusmot waren gebruikt, uit stedelijke gebieden waar dit niet was gebeurd, en uit bossen. In geen van de 41 onderzochte nesten werden de insecticiden aangetroffen die werden gebruikt tegen de buxusmot. In tabel 1 zijn de bestrijdingsmiddelen weergegeven die wel werden aangetroffen in de dode koolmezen op de verschillende plaatsen.
tabel 1
werkzame stof type aantal nesten middel stad (wel stad (geen bos bestrijding) bestrijding) DDT insecticide 9 9 4 DEET insecticide - - 3 bifenyl-2-ol fungicide 1 5 3 fipronil insecticide 6 2 1 fluralaner insecticide 1 1 1 fluroxypyr meptyl herbicide - 1 - imidacloprid insecticide 1 - - permethrin insecticide 4 3 4 insecticide: gifstof die insecten doodt fungicide: gifstof die schimmels doodt herbicide: gifstof die planten doodt$$, 'inline'),
  ('66883906-fba3-49f1-a2d0-9dd8c1ba1022', '37f844eb-46da-4308-b3c9-a5d59e4a5dc0', $$DDT, al lang verboden, toch aangetroffen in veel dode koolmezen$$,
   $$biologie-vwo-2024-i-koolmezen-dood-door-bestrijding-buxusmot-context5.png$$,
   $$Verontrustend was de aanwezigheid van DDT in veel van de dode jonge koolmezen. DDT is al meer dan 50 jaar een verboden stof in Nederland. Deze gegevens laten zien hoe slecht afbreekbaar dit gif is.$$, 'inline'),
  ('0edb1304-20f6-4e85-bb94-58e1d10110c7', '37f844eb-46da-4308-b3c9-a5d59e4a5dc0', $$de herbicide fluroxypyr meptyl aangetroffen in koolmezen uit één nest$$,
   $$biologie-vwo-2024-i-koolmezen-dood-door-bestrijding-buxusmot-context6.png$$,
   $$De onderzoekers troffen in de koolmezen uit één nest de herbicide fluroxypyr meptyl aan.$$, 'inline'),
  ('9e88331b-2ce0-41cc-93ce-4c25730c0f33', '37f844eb-46da-4308-b3c9-a5d59e4a5dc0', $$insecticiden tegen vlooien en teken bij huisdieren; haren als nestbekleding (afbeelding 2)$$,
   $$biologie-vwo-2024-i-koolmezen-dood-door-bestrijding-buxusmot-context7.png$$,
   $$Veel van de insecticiden uit tabel 1 worden gebruikt als bestrijdingsmiddel tegen vlooien en teken bij honden en katten. Henriëtte ontvlooit haar hond elke vier weken met zo’n middel. Misschien hebben jonge koolmezen in haar tuin de gifstoffen via de huid opgenomen na contact met de haren van de hond. Koolmezen gebruiken haren namelijk als binnenbekleding van het nest (afbeelding 2).
afbeelding 2$$, 'inline'),
  ('e7eb8375-012e-4a21-9658-5511d9d75b67', '37f844eb-46da-4308-b3c9-a5d59e4a5dc0', $$opname van gifstoffen verloopt makkelijker via de darm dan via de huid$$,
   $$biologie-vwo-2024-i-koolmezen-dood-door-bestrijding-buxusmot-context8.png$$,
   $$Gifstoffen kunnen echter veel gemakkelijker via de darm worden opgenomen dan via de huid.$$, 'inline'),
  ('0be8b2c1-442f-487f-af45-b54348584a9d', '37f844eb-46da-4308-b3c9-a5d59e4a5dc0', $$bestrijdingsmiddelen in nestharen aangetroffen; krantenkop over vlooien- en tekengif$$,
   $$biologie-vwo-2024-i-koolmezen-dood-door-bestrijding-buxusmot-context9.png$$,
   $$Het Centrum voor Landbouw en Milieu heeft ook de haren uit nestjes met dode koolmeesjongen onderzocht. De gevonden haren bleken permethrin, DEET, fipronil en imidacloprid te bevatten. Een landelijk dagblad publiceerde na dit onderzoek een artikel met de volgende kop: “Koolmeesjes sterven massaal door vlooien- en tekengif” Toen Henriëtte dat las voelde ze zich weer schuldig aan de dood van de koolmeesjongen.$$, 'inline'),
  ('8d7f83f3-58bb-4ef7-9925-37e6e9ce40d7', '3b84ae88-2767-4f56-878d-dbe045a1a716', $$inleiding: drop en zoethoutthee kunnen hoge bloeddruk veroorzaken$$,
   $$biologie-vwo-2024-i-drop-context1.png$$,
   $$Anna heeft last van een hoge bloeddruk. Als ze voor controle naar haar huisarts gaat, vraagt de huisarts of ze vaak drop eet of zoethoutthee drinkt. Bepaalde stoffen in deze voedingsmiddelen kunnen namelijk een hoge bloeddruk veroorzaken.$$, 'inline'),
  ('d3bcb915-6649-42fc-89fe-cc595c4425a3', '3b84ae88-2767-4f56-878d-dbe045a1a716', $$glycyrrhizine (GL) wordt omgezet in glycyrrhetinezuur (GA); enterohepatische circulatie (afbeelding 1)$$,
   $$biologie-vwo-2024-i-drop-context2.png$$,
   $$afbeelding 1 Drop en zoethoutthee bevatten glycyrrhizine (GL). Deze stof zorgt voor de typische dropsmaak en heeft een grote zoetkracht. GL wordt in de darmen door darmbacteriën gehydrolyseerd. Hierbij ontstaat glycyrrhetinezuur (GA), dat wordt opgenomen in het bloed. In de lever wordt een gedeelte van het GA omgezet in een aantal verschillende stoffen die via de gal worden afgevoerd. Een gedeelte daarvan wordt in de darm weer omgezet in GA en vervolgens opgenomen en getransporteerd naar de lever. Deze cyclus heet de enterohepatische circulatie (afbeelding 1).$$, 'inline'),
  ('3248bf0d-2f45-4606-8d39-8c706be11bc7', '3b84ae88-2767-4f56-878d-dbe045a1a716', $$drie uitspraken over de aanwezigheid van GA in het lichaam$$,
   $$biologie-vwo-2024-i-drop-context3.png$$,
   $$Over de aanwezigheid van GA in het lichaam worden de volgende uitspraken gedaan:
1 GA komt alleen terecht in de lever via de poortader.
2 Door de enterohepatische circulatie duurt het langer voordat GA volledig uit het lichaam is verwijderd.
3 Een trage passage van de voedselbrij in de darm verlaagt de hoeveelheid GA in het lichaam.$$, 'inline'),
  ('30dec9ae-af70-4e39-a024-e3b8e6fea0ff', '3b84ae88-2767-4f56-878d-dbe045a1a716', $$GA activeert mineralocorticoïd-receptoren in nierbuiscellen en remt 11β-HSD2 (afbeelding 2)$$,
   $$biologie-vwo-2024-i-drop-context4.png$$,
   $$GA heeft effect op bepaalde cellen in de nierbuisjes (afbeelding 2). In het grondplasma van deze cellen bevinden zich mineralocorticoïd-receptoren. Door binding van cortisol wordt een mineralocorticoïd-receptor (MR) geactiveerd. De geactiveerde MR verplaatst zich naar de kern, waar dit complex bindt aan een hormoon-respons-element (HRE). Daardoor komen bepaalde genen tot expressie, wat leidt tot de synthese van Na⁺-kanalen die in het celmembraan terechtkomen. GA verhindert de werking van het enzym 11β-HSD2 in deze niercellen. Dit enzym zet normaliter cortisol om in cortison. Cortison kan niet binden aan de MR.
Afbeelding 2$$, 'inline'),
  ('4ce6f293-fedd-4fb4-9cc7-26dbfa9b881a', '3b84ae88-2767-4f56-878d-dbe045a1a716', $$de geactiveerde MR is betrokken bij de synthese van Na⁺-kanalen, als transcriptiefactor$$,
   $$biologie-vwo-2024-i-drop-context5.png$$,
   $$De geactiveerde MR is als transcriptiefactor betrokken bij de synthese van Na⁺-kanalen.$$, 'inline'),
  ('0db077f0-623d-46fe-aff6-74b8ed47467e', '3b84ae88-2767-4f56-878d-dbe045a1a716', $$GA-opname verhoogt de osmotische waarde van het bloed$$,
   $$biologie-vwo-2024-i-drop-context6.png$$,
   $$De opname van GA leidt tot een toename van de osmotische waarde van het bloed.$$, 'inline'),
  ('9eb4d1c6-c832-4a5f-9857-9763d5c63120', '3b84ae88-2767-4f56-878d-dbe045a1a716', $$verhoogde osmotische waarde leidt tot hoge bloeddruk en kan oedeem veroorzaken$$,
   $$biologie-vwo-2024-i-drop-context7.png$$,
   $$De toename van de osmotische waarde leidt tot een hoge bloeddruk. Dit kan oedeem veroorzaken.$$, 'inline'),
  ('61970b62-4f36-4d46-996d-9358290f95df', '3b84ae88-2767-4f56-878d-dbe045a1a716', $$GA-gehalte en dagadvies voor verschillende soorten drop$$,
   $$biologie-vwo-2024-i-drop-context8.png$$,
   $$De hoeveelheid glycyrrhizine in drop wordt aangegeven met het GA-gehalte. Het advies voor de hoeveelheid drop die je per dag veilig kan eten, gaat uit van een ‘no effect level’ van 2,0 mg GA per kilogram lichaamsgewicht per dag. Mensen die een hoge bloeddruk hebben zoals Anna, moeten deze waarde door 10 delen. Hieronder is het GA-gehalte van verschillende soorten drop vermeld. Een dropje weegt gemiddeld 5 gram.
soort drop GA-gehalte (mg/kg) zoete drop 1259 mild-zoute drop 801 dubbelzoute drop 343$$, 'inline'),
  ('a0b54462-934f-4457-b66c-0201189304c8', 'ed75a978-9702-43b2-94fc-d6c31d3ef3a2', $$inleiding: Fabio lijdt aan bonenziekte (favisme)$$,
   $$biologie-vwo-2024-i-bonenziekte-context1.png$$,
   $$De burgemeester van een Italiaans dorp heeft het verbouwen van tuinbonen verboden vanwege Fabio, een jongen uit het dorp die lijdt aan bonenziekte (favisme). Het eten van tuinbonen of het inademen van pollen van tuinboonplanten leidt bij Fabio tot een versnelde afbraak van rode bloedcellen, waardoor een levensbedreigende situatie kan ontstaan.$$, 'inline'),
  ('b0a970be-7d5b-4eb8-892f-6e15eddfc451', 'ed75a978-9702-43b2-94fc-d6c31d3ef3a2', $$G6PD-mutatie verstoort de pentose-fosfaatweg (PPP); NADPH en glutathion (afbeelding 1)$$,
   $$biologie-vwo-2024-i-bonenziekte-context2.png$$,
   $$Bonenziekte is het gevolg van een mutatie in het gen dat codeert voor het enzym glucose-6-fosfaatdehydrogenase (G6PD). Hierdoor is bij Fabio dit enzym minder goed werkzaam. G6PD katalyseert de eerste reactie in de pentose-fosfaatweg (‘pentose phosphate pathway’ of PPP). De PPP (afbeelding 1) is een stofwisselingsroute waarbij glucose- moleculen worden omgezet in pentosemoleculen (C₅-moleculen). Hierbij worden ook NADPH-moleculen gevormd. NADPH (bekend van de fotosynthese bij planten) is in menselijke cellen nodig bij de productie van bepaalde organische stoffen zoals glutathion. Glutathion kan schadelijke reactieve zuurstofmoleculen zoals O₂⁻ onschadelijk maken (afbeelding 1).
afbeelding 1$$, 'inline'),
  ('b90c340b-b10f-4cb6-acd6-3a9685078ed7', 'ed75a978-9702-43b2-94fc-d6c31d3ef3a2', $$in de PPP wordt NADPH gevormd$$,
   $$biologie-vwo-2024-i-bonenziekte-context3.png$$,
   $$In de PPP wordt NADPH gevormd.$$, 'inline'),
  ('b4994741-9876-471b-8ce0-9ec513ff7559', 'ed75a978-9702-43b2-94fc-d6c31d3ef3a2', $$de PPP is betrokken bij de productie van vetzuren$$,
   $$biologie-vwo-2024-i-bonenziekte-context4.png$$,
   $$De PPP is betrokken bij de productie van vetzuren. Met behulp van afbeelding 1 kan worden afgeleid wat het gevolg is voor de productie van vetzuren als G6PD onwerkzaam is.$$, 'inline'),
  ('24551af5-962d-431e-ab39-60afcbe40aa3', 'ed75a978-9702-43b2-94fc-d6c31d3ef3a2', $$G6PD-tekort leidt tot glutathiontekort, oxidatie van hemoglobine en hemolyse in rode bloedcellen$$,
   $$biologie-vwo-2024-i-bonenziekte-context5.png$$,
   $$In de rode bloedcellen wordt normaal ongeveer 30% van de glucose via de PPP gedissimileerd. Zo ontstaat er voldoende glutathion om reactieve zuurstofmoleculen onschadelijk te maken. Reactieve zuurstofmoleculen kunnen ontstaan door infecties, door gebruik van bepaalde medicijnen en ook door stoffen in tuinboonplanten. Doordat er bij Fabio te weinig G6PD-activiteit is in zijn rode bloedcellen, is er een tekort aan glutathion. Als Fabio tuinbonen eet of pollen van tuinboonplanten inademt, hopen reactieve zuurstofmoleculen zich op in zijn rode bloedcellen en veroorzaken ze oxidatie van hemoglobine. Hierdoor denatureert de hemoglobine en vormt klonten. Doordat de rode bloedcellen vervolgens openbarsten (hemolyse), ontstaat bloedarmoede.$$, 'inline'),
  ('0cf52ff1-9572-44c8-9d46-19d7ebba8feb', 'ed75a978-9702-43b2-94fc-d6c31d3ef3a2', $$in andere celtypen wordt bij G6PD-tekort extra G6PD aangemaakt$$,
   $$biologie-vwo-2024-i-bonenziekte-context6.png$$,
   $$In de andere cellen van Fabio wordt de ophoping van reactieve zuurstofmoleculen beter bestreden, doordat extra G6PD wordt aangemaakt als er te weinig G6PD-activiteit is.$$, 'inline'),
  ('cb718edc-58c5-458b-9dba-bbfdce0b5c74', 'ed75a978-9702-43b2-94fc-d6c31d3ef3a2', $$symptomen: gele huid en geelverkleuring van het oogwit$$,
   $$biologie-vwo-2024-i-bonenziekte-context7.png$$,
   $$Symptomen die Fabio kan krijgen na het eten van tuinbonen, zijn een gele huid en geelverkleuring van zijn oogwit.$$, 'inline'),
  ('99c8866b-84db-4e73-b1a5-30bfafc26b0d', 'ed75a978-9702-43b2-94fc-d6c31d3ef3a2', $$ademhaling en hartslag van Fabio veranderden na het eten van tuinbonen$$,
   $$biologie-vwo-2024-i-bonenziekte-context8.png$$,
   $$Nadat Fabio een keer tuinbonen had gegeten, veranderden zijn ademhaling en hartslag.$$, 'inline'),
  ('51f8a642-54a7-4ebf-906b-6703bedecf24', 'ed75a978-9702-43b2-94fc-d6c31d3ef3a2', $$G6PD-mutaties zijn meestal puntmutaties of kleine deleties$$,
   $$biologie-vwo-2024-i-bonenziekte-context9.png$$,
   $$Er zijn verschillende mutaties van het G6PD-gen bekend. Het zijn met name puntmutaties en kleine deleties, die leiden tot een minder goed werkzaam G6PD-enzym.$$, 'inline'),
  ('424e708d-5cd9-49e0-aa52-f479790f85f6', 'ed75a978-9702-43b2-94fc-d6c31d3ef3a2', $$drie uitspraken over het effect van mutaties in een exon$$,
   $$biologie-vwo-2024-i-bonenziekte-context10.png$$,
   $$Over mutaties worden de volgende uitspraken gedaan:
1 Een deletie van één basenpaar in een exon leidt tot verandering van het leesraam.
2 Elke puntmutatie in een exon heeft effect op de werkzaamheid van het eiwit waarvoor wordt gecodeerd.
3 Een puntmutatie in een exon kan de afwezigheid van het eiwit waarvoor wordt gecodeerd tot gevolg hebben.$$, 'inline'),
  ('3bb7772d-8d9c-407e-b32d-6cf752e37dc0', 'ed75a978-9702-43b2-94fc-d6c31d3ef3a2', $$stamboom van Fabio''s familie; het G6PD-gen ligt op het X-chromosoom (afbeelding 2)$$,
   $$biologie-vwo-2024-i-bonenziekte-context11.png$$,
   $$Fabio is niet de enige in zijn familie met bonenziekte. In afbeelding 2 is een stamboom weergegeven van zijn familie. Het gen voor G6PD ligt op het X-chromosoom. Fabio’s oma Francesca is drager van het gemuteerde G6PD-allel. De kinderen van Francesca zijn in de stamboom met een letter aangegeven.
afbeelding 2$$, 'inline'),
  ('996928f0-dd39-4903-b449-ccdf3df0eafb', 'ed75a978-9702-43b2-94fc-d6c31d3ef3a2', $$Francesca is heterozygote draagster, geen homozygote drager, van het gemuteerde allel$$,
   $$biologie-vwo-2024-i-bonenziekte-context12.png$$,
   $$Francesca heeft de ziekte niet, maar is wel drager. Dat betekent dat ze heterozygoot is. Ook uit het fenotype van een van de kinderen van Francesca blijkt dat Francesca niet homozygoot kan zijn voor het gemuteerde G6PD-allel.$$, 'inline'),
  ('a8b3d1a3-e97b-4c92-bcc9-2cd44c7b7c41', 'ed75a978-9702-43b2-94fc-d6c31d3ef3a2', $$X-inactivatie kan bij draagsters toch tot een G6PD-tekort leiden$$,
   $$biologie-vwo-2024-i-bonenziekte-context13.png$$,
   $$Bij vrouwen die drager zijn van het gemuteerde G6PD-allel kan soms toch een tekort aan werkzaam G6PD ontstaan, doordat in de voorlopercellen van rode bloedcellen een van de X-chromosomen geïnactiveerd wordt.$$, 'inline'),
  ('ec207b20-fa5f-4070-995d-cbc002a0709b', 'ed75a978-9702-43b2-94fc-d6c31d3ef3a2', $$Fabio''s nicht Stella is in verwachting van een jongen$$,
   $$biologie-vwo-2024-i-bonenziekte-context14.png$$,
   $$Fabio’s nicht Stella is in verwachting van een jongen.$$, 'inline'),
  ('2fe6140d-b948-4489-a0da-1a5abd41fdc1', 'ed75a978-9702-43b2-94fc-d6c31d3ef3a2', $$frequentie van het gemuteerde G6PD-allel is 20% in een populatie in Nigeria$$,
   $$biologie-vwo-2024-i-bonenziekte-context15.png$$,
   $$Bonenziekte komt relatief veel voor in bepaalde gebieden in Afrika. In een populatie in Nigeria heeft het gemuteerde G6PD-allel een frequentie van 20%.$$, 'inline'),
  ('72ff3bbd-f31d-4653-909e-156855297dc2', 'ed75a978-9702-43b2-94fc-d6c31d3ef3a2', $$hoge G6PD-allelfrequentie in malariagebieden door verminderde gevoeligheid voor malaria$$,
   $$biologie-vwo-2024-i-bonenziekte-context16.png$$,
   $$Met name op plaatsen waar malaria heerst, blijkt het G6PD-allel een hoge frequentie te hebben. Dat komt waarschijnlijk doordat rode bloedcellen die een kleinere hoeveelheid werkzaam G6PD hebben, minder gevoelig zijn voor infectie door de malariaparasiet.$$, 'inline'),
  ('cf75e3db-b23b-4732-850f-e6c5ee163f66', 'ed75a978-9702-43b2-94fc-d6c31d3ef3a2', $$bonenziekte wordt op websites ook wel bonenallergie genoemd$$,
   $$biologie-vwo-2024-i-bonenziekte-context17.png$$,
   $$Op verschillende websites wordt de bonenziekte ook wel bonenallergie genoemd.$$, 'inline'),
  ('cd27d7f1-f0a0-41d4-8326-d9ccabb47904', '183584ec-2119-4582-93ca-b2b980650f1e', $$inleiding: onderzoek van het RIVM naar PFAS via besmette groentetuintjes$$,
   $$biologie-vwo-2024-i-pfas-in-groentetuintjes-context1.png$$,
   $$In Nederland ontstond grote ophef toen PFAS (poly- en perfluoralkylstoffen) werden aangetroffen in afvalwater, oppervlaktewater en zelfs drinkwater. PFAS leveren namelijk risico’s op voor de volksgezondheid en het milieu. Wetenschappers van het RIVM (Rijksinstituut voor Volksgezondheid en Milieu) onderzochten of PFAS via besmette groentetuintjes terecht kunnen komen in voedsel voor mensen.$$, 'inline'),
  ('d4dcd19d-f958-477d-94f2-90e08f603119', '183584ec-2119-4582-93ca-b2b980650f1e', $$PFAS en PFOA als synthetische, kankerverwekkende stoffen (afbeelding 1)$$,
   $$biologie-vwo-2024-i-pfas-in-groentetuintjes-context2.png$$,
   $$PFAS zijn synthetische stoffen die afbeelding 1 onder andere worden gebruikt voor de productie van waterafstotende kleding en verpakkingsfolies. Een van deze stoffen is PFOA (perfluoroctaanzuur, afbeelding 1). Onderzoek bij proefdieren heeft aangetoond dat PFOA onder andere lever- en niertumoren kan veroorzaken. Ook tast de stof het immuunsysteem aan. Het gebruik van PFOA is daarom nu verboden.$$, 'inline'),
  ('3b94e21a-a73d-44d8-9caa-7c9904bfd341', '183584ec-2119-4582-93ca-b2b980650f1e', $$PFOA wordt nauwelijks afgebroken; grenswaarde afgeleid van rattenonderzoek$$,
   $$biologie-vwo-2024-i-pfas-in-groentetuintjes-context3.png$$,
   $$PFOA wordt nauwelijks afgebroken of uitgescheiden door het lichaam van de mens. Voor PFOA is de grenswaarde een dagelijkse inname van 0,63 ng/kg lichaamsgewicht per dag. Deze waarde is afgeleid van de waarde van 750 ng/kg lichaamsgewicht per dag die uit onderzoek bij ratten kwam.$$, 'inline'),
  ('b79c3c0f-224b-4d72-93d1-1ef09e11a8c5', '183584ec-2119-4582-93ca-b2b980650f1e', $$binding van PFOA aan plasma-eiwitten belemmert de uitscheiding$$,
   $$biologie-vwo-2024-i-pfas-in-groentetuintjes-context4.png$$,
   $$PFOA wordt nauwelijks uitgescheiden doordat veel PFOA-moleculen binden aan plasma-eiwitten in het bloed. De PFOA-moleculen die niet gebonden zijn, kunnen wel worden uitgescheiden.$$, 'inline'),
  ('f3760ad2-f9b2-4c62-ba82-61f34f4f7b1d', '183584ec-2119-4582-93ca-b2b980650f1e', $$PFOA heeft geen mutagene effecten, maar veroorzaakt toch meer tumoren$$,
   $$biologie-vwo-2024-i-pfas-in-groentetuintjes-context5.png$$,
   $$Hoewel PFOA geen mutagene effecten heeft, wordt in proefdieren toch een verhoogd aantal tumoren gevonden.$$, 'inline'),
  ('0220f2d3-7292-4450-a737-0c1fff09aa76', '183584ec-2119-4582-93ca-b2b980650f1e', $$tumoren ontstaan door mutaties in genen met een regulerende functie bij celdeling$$,
   $$biologie-vwo-2024-i-pfas-in-groentetuintjes-context6.png$$,
   $$Tumoren kunnen – onder invloed van mutagene factoren – ontstaan door mutaties in bepaalde genen die een regulerende functie hebben bij celdeling.$$, 'inline'),
  ('2dbfcb9a-cc8d-4af1-bce3-69a3bee22e44', '183584ec-2119-4582-93ca-b2b980650f1e', $$tumortoename mogelijk door een verminderde hoeveelheid T-lymfocyten$$,
   $$biologie-vwo-2024-i-pfas-in-groentetuintjes-context7.png$$,
   $$De toename van het aantal tumoren bij de proefdieren zou een gevolg kunnen zijn van een verminderde hoeveelheid T-lymfocyten.$$, 'inline'),
  ('d26b631f-c26d-4801-9b82-53c99e3cad30', '183584ec-2119-4582-93ca-b2b980650f1e', $$PFOA-onderzoek bij volkstuintjes in Dordrecht en Bilthoven (afbeelding 2)$$,
   $$biologie-vwo-2024-i-pfas-in-groentetuintjes-context8.png$$,
   $$Door de besmetting van grond- en oppervlaktewater met PFAS zouden deze stoffen terecht kunnen komen in voedselgewassen die in de directe omgeving geteeld worden. Om te onderzoeken of dit werkelijk gebeurt, werden groenten uit volkstuintjes in de omgeving van een groot chemiebedrijf in Dordrecht getest op aanwezigheid van PFOA. Behalve groenten uit volkstuintjes in de omgeving van het chemisch bedrijf in Dordrecht werden ook groenten uit volkstuintjes in Bilthoven, dat 60 km verderop ligt, getest op de aanwezigheid van PFOA. De resultaten staan in afbeelding 2.
afbeelding 2$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('c085bbac-2872-403e-b49b-6407cea089cf', '3f704958-4409-4a7c-9c44-595b84c3ac6f', 1,
   '[{"domain": "Orgaan- en organismeniveau", "subdomain": "Zelfregulatie van het organisme"}]'::jsonb,
   '["synaps", "neurotransmitter", "receptorbinding", "heropname"]'::jsonb,
   $$Beoordelen van uitspraken over de werking van nicotine en dopamine op de synaps in het beloningscentrum.$$,
